const event = {
  eventId: 'evt_9f2...',        // idempotency key for the WHOLE fan-out
  userId: 'u_42',
  type: 'order.shipped',
  data: { orderId: 'o_918', carrier: 'ups' },
};

// channels are a user preference lookup, not a property of the event
const channels = await prefs.channelsFor(event.userId, event.type);
// e.g. ['push', 'email']

function render(channel, event) {
  const tpl = templates.lookup(event.type, channel);
  return tpl.render(event.data);   // { title, body } or { subject, html }
}

const rendered = channels.map((ch) => ({ channel: ch, body: render(ch, event) }));

async function send(channel, event, body) {
  const key = `${event.eventId}:${channel}`;
  return providers[channel].deliver({ idempotencyKey: key, ...body });
}

async function attempt(channel, event, body, tries = 0) {
  try {
    await send(channel, event, body);
  } catch (e) {
    if (e.permanent) return deadLetter.push({ channel, event, reason: e.code });
    if (tries >= 5) {
      return deadLetter.push({ channel, event, reason: 'retries_exhausted' });
    }

    const delay = Math.min(30_000, 2 ** tries * 500) * (0.5 + Math.random());
    await sleep(delay);
    return attempt(channel, event, body, tries + 1);
  }
}

function shouldSendNow(userId, channel) {
  if (isQuietHours(userId)) return false;              // delay, don't drop
  if (rateLimiter.exceeded(userId, channel)) return false;  // digest instead
  return true;
}

async function finalSend(channel, event, body) {
  if (await prefs.isUnsubscribed(event.userId, channel, event.type)) return;
  return attempt(channel, event, body);
}
